    s.sort()
    s_by_first = sorted(s, key=lambda x: x[0])
    s_by_second = sorted(s, key=lambda x: x[1])

    # Check if the sequence is already sorted by either first or second element
    if s == s_by_first or s == s_by_second:
        return 0

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Fill the DP table
    for i in range(n + 1):
        for j in range(n + 1):
