                continue
            if i > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD

    # Calculate the result
    result = 0
    for i in range(n + 1):
        for j in range(n + 1):
            if i + j == n:
                result = (result + dp[i][j]) % MOD

    return result

